namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "English", Abbreviation = "ENG" },
        new() { Id = 4, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private readonly List<Course> _courses =
    [
        new()
        {
            Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
            Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, data structures, and object-oriented design principles.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, IsFeatured = true,
            InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy."
        },
        new()
        {
            Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = 1, IsFeatured = true,
            InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and competitive programming. Previously a senior engineer at Google, he brings industry experience to the classroom."
        },
        new()
        {
            Id = 3, CourseCode = "CS 310", Title = "Database Systems",
            Description = "Introduction to relational database design, SQL, normalization, indexing, and transaction management. Includes a semester-long project building a full database application.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, IsFeatured = false,
            InstructorName = "Prof. Maria Lopez", InstructorBio = "Prof. Lopez is a database researcher with expertise in distributed systems. She consults for several Fortune 500 companies on data architecture."
        },
        new()
        {
            Id = 4, CourseCode = "MATH 151", Title = "Calculus I",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
            Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, IsFeatured = true,
            InstructorName = "Dr. Robert Williams", InstructorBio = "Dr. Williams is an award-winning mathematics educator who has taught calculus for over 20 years. He is known for making complex concepts accessible and engaging."
        },
        new()
        {
            Id = 5, CourseCode = "MATH 250", Title = "Linear Algebra",
            Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science and engineering.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 2, IsFeatured = false,
            InstructorName = "Dr. Emily Nakamura", InstructorBio = "Dr. Nakamura researches applications of linear algebra in machine learning. She holds joint appointments in Mathematics and Computer Science."
        },
        new()
        {
            Id = 6, CourseCode = "ENG 110", Title = "College Writing",
            Description = "Develop skills in academic writing including argumentation, research methods, citation, and revision. Emphasis on clear, persuasive prose.",
            Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 3, IsFeatured = false,
            InstructorName = "Prof. David Thompson", InstructorBio = "Prof. Thompson is a published author and writing instructor with expertise in rhetoric and composition. He has mentored hundreds of students in developing their writing voice."
        },
        new()
        {
            Id = 7, CourseCode = "ENG 250", Title = "American Literature",
            Description = "Survey of major American literary works from the colonial period to the present. Explores themes of identity, freedom, and the American experience.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 3, IsFeatured = false,
            InstructorName = "Dr. Angela Foster", InstructorBio = "Dr. Foster specializes in 20th-century American fiction. Her recent book on the Harlem Renaissance received the National Book Critics Circle Award."
        },
        new()
        {
            Id = 8, CourseCode = "PHYS 201", Title = "General Physics I",
            Description = "Mechanics, waves, and thermodynamics. Calculus-based approach with weekly laboratory sessions.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:50 PM", DepartmentId = 4, IsFeatured = true,
            InstructorName = "Dr. Michael Okafor", InstructorBio = "Dr. Okafor is an experimental physicist whose research focuses on condensed matter physics. He brings hands-on laboratory expertise to introductory physics courses."
        },
        new()
        {
            Id = 9, CourseCode = "HIST 101", Title = "World History to 1500",
            Description = "Survey of world civilizations from prehistory through the late medieval period. Examines political, economic, social, and cultural developments across regions.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", DepartmentId = 5, IsFeatured = false,
            InstructorName = "Dr. Patricia Hernandez", InstructorBio = "Dr. Hernandez is a medieval historian specializing in cross-cultural exchange along the Silk Road. She has conducted fieldwork in Central Asia and the Middle East."
        },
        new()
        {
            Id = 10, CourseCode = "HIST 220", Title = "Modern European History",
            Description = "Europe from the Enlightenment to the present day. Topics include revolutions, industrialization, world wars, and European integration.",
            Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", DepartmentId = 5, IsFeatured = false,
            InstructorName = "Prof. Andrew Klein", InstructorBio = "Prof. Klein is an expert on 20th-century European political history. He previously served as a visiting scholar at Oxford and the Sorbonne."
        },
    ];

    private readonly List<EnrollmentRequest> _enrollmentRequests = [];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

