@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search courses, instructors..." />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Credits</th>
                <th>Instructor</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in _courses)
            {
                <tr>
                    <td>@course.CourseCode</td>
                    <td>@course.Title</td>
                    <td>@course.Credits</td>
                    <td>@course.InstructorName</td>
                    <td>@course.Schedule</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-secondary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private IReadOnlyList<Course> _courses = [];
    private IReadOnlyList<Department> _departments = [];

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.SearchCourses(Search, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>@(_course?.Title ?? "Course Not Found")</PageTitle>

@if (_course is null)
{
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="courses" class="btn btn-primary">Back to Courses</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="courses?departmentId=@_course.DepartmentId">@_department?.Name</a></li>
            <li class="breadcrumb-item active">@_course.CourseCode</li>
        </ol>
    </nav>

    <h1>@_course.CourseCode — @_course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h2>Description</h2>
            <p>@_course.Description</p>

            <h2 class="mt-4">Instructor</h2>
            <h5>@_course.InstructorName</h5>
            <p>@_course.InstructorBio</p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Course Details</h5>
                    <dl>
                        <dt>Credits</dt>
                        <dd>@_course.Credits</dd>
                        <dt>Schedule</dt>
                        <dd>@_course.Schedule</dd>
                        <dt>Department</dt>
                        <dd>@_department?.Name</dd>
                    </dl>
                    <a href="enroll?courseId=@_course.Id" class="btn btn-success w-100">Request Enrollment</a>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? _course;
    private Department? _department;

    protected override void OnInitialized()
    {
        _course = Catalog.GetCourse(Id);
        if (_course is not null)
        {
            _department = Catalog.GetDepartment(_course.DepartmentId);
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Request Enrollment</h1>
<p>Fill out the form below to submit an enrollment request.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted!</h4>
        <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for <strong>@_selectedCourseTitle</strong> has been received. You will be contacted with next steps.</p>
    </div>
    <a href="courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <form method="post" @formname="enrollment" class="col-md-8">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" id="studentName" name="_model.StudentName" value="@_model.StudentName" class="form-control" required />
            @if (_errors.ContainsKey(nameof(_model.StudentName)))
            {
                <div class="text-danger">@_errors[nameof(_model.StudentName)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" id="studentId" name="_model.StudentId" value="@_model.StudentId" class="form-control" required />
            @if (_errors.ContainsKey(nameof(_model.StudentId)))
            {
                <div class="text-danger">@_errors[nameof(_model.StudentId)]</div>
            }
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select id="courseId" name="_model.CourseId" class="form-select" required>
                <option value="">— Select a course —</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id" selected="@(_model.CourseId == course.Id)">@course.CourseCode — @course.Title</option>
                }
            </select>
            @if (_errors.ContainsKey(nameof(_model.CourseId)))
            {
                <div class="text-danger">@_errors[nameof(_model.CourseId)]</div>
            }
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
        <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private IReadOnlyList<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;
    private Dictionary<string, string> _errors = new();

    protected override void OnInitialized()
    {
        _courses = Catalog.GetAllCourses();

        if (CourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        if (HttpMethods.IsPost(HttpContextAccessor?.HttpContext?.Request.Method ?? "GET"))
        {
            _errors = Validate(_model);
            if (_errors.Count == 0)
            {
                Catalog.SubmitEnrollmentRequest(_model);
                _selectedCourseTitle = _courses.FirstOrDefault(c => c.Id == _model.CourseId)?.Title ?? "Unknown";
                _submitted = true;
            }
        }
    }

    [CascadingParameter]
    private HttpContext? HttpContextValue { get; set; }

    [Inject]
    private IHttpContextAccessor? HttpContextAccessor { get; set; }

    private static Dictionary<string, string> Validate(EnrollmentRequest model)
    {
        var errors = new Dictionary<string, string>();
        if (string.IsNullOrWhiteSpace(model.StudentName))
            errors[nameof(model.StudentName)] = "Name is required.";
        if (string.IsNullOrWhiteSpace(model.StudentId))
            errors[nameof(model.StudentId)] = "Student ID is required.";
        if (model.CourseId <= 0)
            errors[nameof(model.CourseId)] = "Please select a course.";
        return errors;
    }
}

